#!/usr/bin/env bash
# @@REPO@@ — per-repo validation gate (stack: @@STACK@@).
# Generated by tools/validate/generate.sh. Edit freely afterwards; the generator
# will not overwrite this file without --force.
#
#   quick   seconds. Config integrity only. No Docker, no build.
#   full    hours. Guarded behind an explicit opt-in.
set -uo pipefail
# shellcheck source=lib/validate-lib.sh
source "$(dirname "${BASH_SOURCE[0]}")/lib/validate-lib.sh"

TIER="$(tier_or_die "${1:-quick}")"

# --- quick -----------------------------------------------------------------

check "kas YAML + Makefile parse (make lint)" "python3" 'make lint'

# Orphan gitlinks (mode 160000) with no .gitmodules once made kas clone a layer
# at the repo root and overwrite this repo's own .git. Prevention is cheap.
assert "no orphan gitlinks in layers/" \
  'orphans=$(git ls-files -s layers/ 2>/dev/null | awk "\$1==\"160000\"{print \$4}")
   if [ -n "$orphans" ] && [ ! -f .gitmodules ]; then
     echo "orphan gitlink(s) with no .gitmodules — kas may clobber the repo root:"
     echo "$orphans"; exit 1
   fi'

check "build prerequisites (make test)" "docker curl" 'make test'

[ "$TIER" = "quick" ] && { report "$TIER"; exit $?; }

# --- full ------------------------------------------------------------------

check "image metadata (make validate)" "docker curl" 'make validate'

if [ "${ARCHES_VALIDATE_BUILD_IMAGE:-0}" = "1" ]; then
  ARCHES_VALIDATE_TIMEOUT=${ARCHES_VALIDATE_TIMEOUT_IMAGE:-21600} \
    check "full image build" "docker curl" 'make build'
else
  block "full image build" "not attempted; hours-long. Set ARCHES_VALIDATE_BUILD_IMAGE=1 to run it."
fi

report "$TIER"
